const results = [];

for (const item of $input.all()) {
  const body = item.json.body || {};

  if (Array.isArray(body.entry)) {
    // Meta webhook. One request can hold several entries and changes.
    for (const entry of body.entry) {
      for (const change of entry.changes || []) {
        const value = change.value || {};
        let platform;
        if (change.field === 'comments') {
          platform = 'instagram';
        } else if (change.field === 'feed' && value.item === 'comment' && value.verb === 'add') {
          // Page feed also sends likes, new posts, edits and deletions: only new comments get through
          platform = 'facebook';
        } else {
          continue;
        }
        results.push({
          json: {
            platform,
            commentId: value.comment_id || value.id || '',
            commentText: value.message || value.text || '',
            authorId: (value.from && value.from.id) || '',
            authorHandle: (value.from && (value.from.username || value.from.name)) || '',
            postId: value.post_id || (value.media && value.media.id) || '',
            postUrl: value.permalink_url || '',
            timestamp: String(value.created_time || new Date().toISOString()),
          },
        });
      }
    }
  } else {
    // TikTok / LinkedIn: one comment, or { comments: [...] }, POSTed by your scraper
    const comments = Array.isArray(body.comments) ? body.comments : [body];
    for (const c of comments) {
      results.push({
        json: {
          platform: String(c.platform || 'unknown').toLowerCase(),
          commentId: c.commentId || '',
          commentText: c.text || c.commentText || '',
          authorId: c.authorId || '',
          authorHandle: c.author || c.authorHandle || '',
          postId: c.postId || '',
          postUrl: c.postUrl || '',
          timestamp: c.timestamp || new Date().toISOString(),
        },
      });
    }
  }
}

// Drop anything without an ID or text
return results.filter((r) => r.json.commentId && r.json.commentText);

// Only comments from the last hour. Without this, the first run would reply to your 50 most recent comments, however old.
const MAX_AGE_MINUTES = 60;
const cutoff = Date.now() - MAX_AGE_MINUTES * 60 * 1000;

const response = $input.first().json;
const comments = response.items || [];
return comments
  .filter((c) => new Date(c.snippet.topLevelComment.snippet.publishedAt).getTime() >= cutoff)
  .map((c) => {
    const top = c.snippet.topLevelComment.snippet;
    return {
      json: {
        platform: 'youtube',
        commentId: c.snippet.topLevelComment.id,
        commentText: top.textOriginal,
        authorId: top.authorChannelId ? top.authorChannelId.value : '',
        authorHandle: top.authorDisplayName,
        postId: c.snippet.videoId,
        postUrl: 'https://www.youtube.com/watch?v=' + c.snippet.videoId,
        timestamp: top.publishedAt,
      },
    };
  });

const out = $json;
let text = '';
if (typeof out.merged_response === 'string') text = out.merged_response;
else if (Array.isArray(out.content)) text = out.content.filter((p) => p.type === 'text').map((p) => p.text).join('');
else if (typeof out.text === 'string') text = out.text;
else if (typeof out.message === 'string') text = out.message;
else text = JSON.stringify(out);

let ai;
try {
  const match = text.match(/\{[\s\S]*\}/);
  ai = JSON.parse(match ? match[0] : text);
  if (typeof ai.intent !== 'string') throw new Error('no intent');
} catch (e) {
  // Claude didn't return usable JSON: don't post anything, email the owner instead
  ai = { intent: 'error', isLead: false, shouldReply: false, reply: '' };
}

const comment = $('Skip Our Own Comments').item.json;
return {
  json: {
    platform: comment.platform,
    commentId: comment.commentId,
    commentText: comment.commentText,
    authorId: comment.authorId,
    authorHandle: comment.authorHandle,
    postId: comment.postId,
    postUrl: comment.postUrl,
    timestamp: comment.timestamp,
    intent: ai.intent,
    isLead: ai.isLead === true,
    shouldReply: ai.shouldReply === true && Boolean(ai.reply),
    reply: ai.reply || '',
  },
};

